export function language(){return current;}
export function locale(){return current==='ar'?'ar-EG':'en-EG';}
export function direction(){return current==='ar'?'rtl':'ltr';}
export function setLanguage(value:Language){current=value;}
/** Only display labels are translated; stored values and business rules stay unchanged. */
export function t(value:any):any{if(typeof value!=='string'||current==='ar')return value;const key=value.trim();if(translations[key])return value.replace(key,translations[key]);if(key.endsWith(' (ج.م)'))return t(key.slice(0,-6))+' (EGP)';if(value.endsWith(' ج.م'))return value.slice(0,-4)+' EGP';return value;}
